 function frame(now){raf=0;if(!active||document.hidden)return;const dt=last?Math.min((now-last)/1000,.07):0;last=now;let moving=Math.abs(state.cx-state.targetCenter.x)+Math.abs(state.cy-state.targetCenter.y)+Math.abs(state.cz-state.targetCenter.z)+Math.abs(state.yaw-state.targetYaw)+Math.abs(state.pitch-state.targetPitch)+Math.abs(state.zoom-state.targetZoom)>.001;if(state.motion){elapsed+=dt;if(!state.selected&&!state.edge&&state.chapter<0)state.targetYaw+=dt*.016;moving=true}if(state.playing){state.year=Math.min(2030,state.year+dt*.19);if(state.year>=2030)state.playing=false;syncTime();moving=true}const ease=reduce()?1:.075;state.cx=mix(state.cx,state.targetCenter.x,ease);state.cy=mix(state.cy,state.targetCenter.y,ease);state.cz=mix(state.cz,state.targetCenter.z,ease);state.yaw=mix(state.yaw,state.targetYaw,ease);state.pitch=mix(state.pitch,state.targetPitch,ease);state.zoom=mix(state.zoom,state.targetZoom,ease);if(dirty||moving){draw();dirty=false}raf=requestAnimationFrame(frame)}
