 function closest(x,y){const node=[...projected].reverse().filter(p=>!p.dim).find(p=>Math.hypot(p.x-x,p.y-y)<Math.max(13,p.r+5));if(node)return{kind:'node',id:node.n.id,x:node.x,y:node.y};let best=null,distance=8;for(const {e,path,focus}of edgePaths){if(!focus)continue;for(let i=1;i<path.length;i++){const a=path[i-1],b=path[i],dx=b.x-a.x,dy=b.y-a.y,t=clamp(((x-a.x)*dx+(y-a.y)*dy)/(dx*dx+dy*dy||1),0,1),d=Math.hypot(x-a.x-t*dx,y-a.y-t*dy);if(d<distance){distance=d;best={kind:'edge',id:e.id,x,y}}}}return best}
