  let drag=null;canvas.addEventListener('pointerdown',e=>{if(e.button!==0)return;drag={x:e.clientX,y:e.clientY,lastX:e.clientX,lastY:e.clientY,moved:false};canvas.setPointerCapture(e.pointerId);q('.u-hover').hidden=true});canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;if(drag){const dx=e.clientX-drag.lastX,dy=e.clientY-drag.lastY;drag.moved ||=Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>5;if(drag.moved){state.targetYaw+=dx*.006;state.targetPitch=clamp(state.targetPitch+dy*.004,-.65,1.5);dirty=true}drag.lastX=e.clientX;drag.lastY=e.clientY}else showHover(closest(x,y),x,y)});canvas.addEventListener('pointerup',e=>{if(drag&&!drag.moved){const r=canvas.getBoundingClientRect(),hit=closest(e.clientX-r.left,e.clientY-r.top);if(hit)hit.kind==='node'?selectNode(hit.id):selectEdge(hit.id)}drag=null;canvas.releasePointerCapture(e.pointerId)});canvas.addEventListener('pointercancel',()=>drag=null);canvas.addEventListener('pointerleave',()=>{if(!drag)showHover(null,0,0)});canvas.addEventListener('wheel',e=>{e.preventDefault();state.targetZoom=clamp(state.targetZoom*Math.exp(-e.deltaY*.001),.6,2.2);dirty=true},{passive:false});canvas.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','=','-','Escape'].includes(e.key)){e.preventDefault();if(e.key==='ArrowLeft')state.targetYaw-=.13;if(e.key==='ArrowRight')state.targetYaw+=.13;if(e.key==='ArrowUp')state.targetPitch=clamp(state.targetPitch-.1,-.65,1.5);if(e.key==='ArrowDown')state.targetPitch=clamp(state.targetPitch+.1,-.65,1.5);if(e.key==='+'||e.key==='=')state.targetZoom=clamp(state.targetZoom*1.15,.6,2.2);if(e.key==='-')state.targetZoom=clamp(state.targetZoom/1.15,.6,2.2);if(e.key==='Escape')clearSelection();dirty=true}});document.addEventListener('visibilitychange',()=>{if(!document.hidden&&active){last=0;if(!raf)raf=requestAnimationFrame(frame)}});
